INSERT INTO "products" ("id","slug","title","base_price","original_price","description","long_description","badge","meta_title","meta_description","images","specs","features","compatibility","faqs","review_count","rating","created_at","status","cost_price") VALUES(1,'gionee-handsfree-3-5mm','Gionee Handsfree 3.5mm',500,700,'Experience premium sound quality with the original Gionee 3.5mm Handsfree. Featuring deep bass, crystal clear vocals, and a durable design, this earphone is perfect for music lovers and daily commuters. The universal 3.5mm jack ensures compatibility with a wide range of devices.','<p>Experience high-fidelity audio with the <strong>Original Gionee 3.5mm Handsfree</strong>. Specially engineered for balanced sound, these earphones deliver deep, punchy bass without overpowering the crisp vocals and clear highs.</p><p>Whether you''re listening to music, watching movies, or taking important calls, the HD microphone ensures your voice is heard loud and clear.</p><h3>Key Highlights</h3><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>100% Original:</strong> Sourced directly for guaranteed authenticity.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Crystal Clear Audio:</strong> High-fidelity sound with 10mm dynamic drivers.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Built-in Mic:</strong> HD microphone for seamless hands-free calls.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>TPE Cable:</strong> High elasticity material prevents tangling and increases durability.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Ergonomic Design:</strong> Comfortable for long-term wear during commutes or workouts.</li></ol>','Best Seller','Gionee 3.5mm Handsfree Price Pakistan | Original PKR 500 | Buy Online','Original Gionee 3.5mm handsfree in Pakistan - PKR 500 (30% off). Crystal clear sound, built-in mic, 1.2m cable. 5/5 rating, 1,000+ reviews. Buy online with COD.','[{"url":"https://cdn.gionee.com.pk/uploads/media/1774022390285-gionee-handsfree-3-5mm-original.jpg","alt":"Gionee Handsfree 3.5mm - Original Price PKR 450"},{"url":"https://cdn.gionee.com.pk/uploads/media/1774022438747-gionee-handsfree-3-5mm-original-jack.jpg","alt":"Gionee Handsfree 3.5mm"},{"url":"https://cdn.gionee.com.pk/uploads/media/1779443248298-zvrnuy.jpg","alt":"Gionee Handsfree 3.5mm"},{"url":"https://cdn.gionee.com.pk/uploads/media/1779443248265-nupil1.jpg","alt":"Gionee Handsfree 3.5mm"}]','[{"label":"Connector Type","value":"3.5mm Audio Jack"},{"label":"Cable Length","value":"1.2 Meters"},{"label":"Driver Size","value":"10mm Dynamic Bass"},{"label":"Microphone","value":"Yes, Built-in HD Mic"},{"label":"Impedance","value":"32Ω"},{"label":"Frequency Range","value":"20Hz - 20kHz"},{"label":"Material","value":"TPE High Elasticity"},{"label":"Color","value":"White"}]','[{"title":"Crystal Clear Audio","description":"10mm dynamic drivers for high-fidelity sound."},{"title":"Built-in HD Mic","description":"Perfect for gaming and seamless hands-free calls."},{"title":"Universal Jack","description":"Compatible with any device featuring a 3.5mm port."},{"title":"Tangle-Free Cable","description":"Durable TPE material for long-lasting daily use."}]','["Android Smartphones with 3.5mm Jack","Feature Phones (Nokia, etc.)","Laptops & Computers","Tablets & iPads (Older gens)","Gaming Consoles (PS4, Xbox Controller)","MP3 Players"]','[{"question":"Is this the original Gionee handsfree?","answer":"Yes, we sell 100% original Gionee handsfree sourced directly. It comes in official packaging with authenticity checks."},{"question":"Does it work with my phone?","answer":"It works with ANY device that has a round 3.5mm headphone jack. If your phone only has a charging port (Type-C/Lightning), you will need a different model or an adapter."},{"question":"What is the warranty period?","answer":"We offer a 7-day replacement warranty for any manufacturing defects. The product is built to last 1-2 years with normal use."},{"question":"Is there a delivery charge?","answer":"We offer FREE delivery on orders above PKR 1000. For single items, standard shipping rates apply."}]',1054,4.7,'2026-05-20 19:32:03','published',250);
INSERT INTO "products" ("id","slug","title","base_price","original_price","description","long_description","badge","meta_title","meta_description","images","specs","features","compatibility","faqs","review_count","rating","created_at","status","cost_price") VALUES(2,'gionee-handsfree-type-c','Gionee Handsfree Type-C',600,850,'Upgrade to digital audio with the Gionee Type-C Handsfree. Built for modern smartphones without headphone jacks, this earphone features a built-in DAC ensuring high-fidelity sound and wide compatibility. Perfect for gaming (zero latency) and high-res music.','<p>Upgrade to superior digital sound with the <strong>Original Gionee Type-C Handsfree</strong>. Equipped with a high-performance built-in DAC (Digital-to-Analog Converter) chip, it provides direct, lossless digital audio transmission for flawless compatibility with modern USB-C smartphones.</p><p>Ideal for music enthusiasts and mobile gamers, it delivers deep bass, pure acoustics, and zero-latency audio sync.</p><h3>Key Highlights</h3><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Digital DAC Chip:</strong> Lossless digital decoder for high-resolution sound.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Wide Compatibility:</strong> Works perfectly with Samsung Galaxy, iPhone 15/16, Xiaomi, OnePlus, and iPad Pro.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>HD Noise-Reduction Mic:</strong> Clear vocals for gaming chats and voice calls.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Angled In-Ear Fit:</strong> Ergonomically shaped earbuds stay secure and reduce ambient noise.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span><strong>Zero Latency:</strong> Wired connection ensures zero audio delay for perfect gaming and streaming.</li></ol>','Trending','Gionee Type-C Handsfree Price Pakistan | Original PKR 600 | USB-C Earphones','Original Gionee Type-C handsfree Pakistan - PKR 600 (30% off). USB-C, noise reduction mic, 10,000+ durable connector. 5/5 rating, 1200+ reviews. Fast delivery.','[{"url":"https://cdn.gionee.com.pk/uploads/media/1774025257633-gionee-handsfree-type-c-original.jpg","alt":"Gionee Handsfree Type-C - Original Price PKR 550"},{"url":"https://cdn.gionee.com.pk/uploads/media/1774025263419-gionee-handsfree-type-c-original-jack.jpg","alt":"Gionee Handsfree Type-C"},{"url":"https://cdn.gionee.com.pk/uploads/media/1774022444473-gionee-handsfree-3-5mm-original-mic.jpg","alt":"Gionee Handsfree Type-C"},{"url":"https://cdn.gionee.com.pk/uploads/media/1774022433767-gionee-handsfree-3-5mm-original-earbuds.jpg","alt":"Gionee Handsfree Type-C"}]','[{"label":"Connector Type","value":"USB Type-C"},{"label":"Chipset","value":"Built-in Digital Decoder (DAC)"},{"label":"Cable Length","value":"1.2 Meters"},{"label":"Driver Size","value":"10mm High-Res"},{"label":"Microphone","value":"Yes, Noise Reduction"},{"label":"Impedance","value":"32Ω"},{"label":"Frequency Range","value":"20Hz - 20kHz"},{"label":"Color","value":"White"}]','[{"title":"Digital DAC Chip","description":"Built-in decoder for Samsung/iPhone 15 compatibility."},{"title":"Lossless Audio","description":"High-resolution digital signal for crystal clear sound."},{"title":"Durable Type-C","description":"Reinforced reversible connector for long life."},{"title":"Zero Latency","description":"Perfect for mobile gaming with no audio lag."}]','["Samsung Galaxy S20, S21, S22, S23, S24 Series","iPhone 15, 15 Pro, 15 Pro Max","Xiaomi / Redmi / POCO Devices","OnePlus & Realme Phones","Google Pixel Series","iPad Pro / Air (USB-C models)","Laptops with USB-C Audio support"]','[{"question":"Will this work with Samsung Galaxy S23?","answer":"Yes! It has a built-in DAC chip which is required for Samsung devices. It works perfectly with the S20, S21, S22, S23, and S24 series."},{"question":"Does it work with iPhone 15?","answer":"Yes, it is fully compatible with the iPhone 15 series and supports music and calls."},{"question":"Is this better than 3.5mm?","answer":"Type-C offers digital signal transmission which can result in cleaner audio. It''s also more durable (reversible connector). If your phone has Type-C only, this is the best wired choice."},{"question":"Is the mic good for gaming?","answer":"Absolutely. The wired connection means zero latency (no lag), and the microphone is positioned for clear voice chat."}]',1232,4.8,'2026-05-20 19:32:03','published',350);
