INSERT INTO "settings" ("key","value","description","updated_at") VALUES('whatsapp_template_confirmation',replace(replace('Hi *{customer_name}*, thank you for placing your order at Gionee Pakistan!\r\n\r\nYour order has been received. Here is your order summary:\r\n\r\n*Order ID:* #{order_id}\r\n*Amount (COD):* PKR {total_amount}\r\n*Address:* {address}\r\n\r\n👉 Reply *YES* to confirm your order.\r\n\r\n_Note: This is an automated message. Leave a message if you have queries; our representative will reply shortly._','\r',char(13)),'\n',char(10)),NULL,'2026-05-25 17:40:54');
INSERT INTO "settings" ("key","value","description","updated_at") VALUES('whatsapp_template_thank_you',replace(replace('Thank you *{customer_name}* for shopping with us!\r\n\r\nYour order *#{order_id}* is confirmed. We are packing it now and will send your tracking link once dispatched.\r\n\r\n_Note: This is an automated message. Leave a message if you have queries; our representative will reply shortly._','\r',char(13)),'\n',char(10)),NULL,'2026-05-25 17:40:54');
INSERT INTO "settings" ("key","value","description","updated_at") VALUES('whatsapp_template_shipped',replace(replace('*📦 Your Order Has Been Shipped!*\r\n\r\nHi *{customer_name}*,\r\n\r\nGreat news! Your order *#{order_id}* has been dispatched.\r\n\r\n*Tracking Number:* {tracking_no}\r\n*Track Here:* {tracking_url}\r\n\r\n_Note: This is an automated message. Leave a message if you have queries; our representative will reply shortly._','\r',char(13)),'\n',char(10)),NULL,'2026-05-25 17:40:54');
