INSERT INTO "resend_email_logs" ("id","type","order_id","recipient","subject","payload","response","error","created_at") VALUES(393,'Admin Alert','#GPK06106','support@gionee.com.pk, aashirblogging@gmail.com','New Order: #GPK06106 - Dilbar','{"from":"Gionee Orders <order@gionee.com.pk>","to":["support@gionee.com.pk","aashirblogging@gmail.com"],"subject":"New Order: #GPK06106 - Dilbar","html":"\n          <h3>New Order Confirmation - #GPK06106</h3>\n          <h4>Customer Details</h4>\n          <p><strong>Name:</strong> Dilbar</p>\n          <p><strong>Phone:</strong> 03087272905</p>\n          <p><strong>Email:</strong> dilbaralimhr@gmail.com</p>\n          <p><strong>City:</strong> Ghotki</p>\n          <p><strong>Address:</strong> Al Madina Kanta Ghotki Near Al Makka Hotel By Pass Ghotki Highway </p>\n          \n          <h4>Order Items</h4>\n          <table style=\"width: 100%; border-collapse: collapse; margin-top: 10px;\">\n            <thead>\n              <tr style=\"background: #f8f8f8;\">\n                <th style=\"padding: 8px; text-align: left;\">Item</th>\n                <th style=\"padding: 8px; text-align: center;\">Qty</th>\n                <th style=\"padding: 8px; text-align: right;\">Price</th>\n              </tr>\n            </thead>\n            <tbody>\n              \n        <tr>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee;\">\n            <div style=\"font-weight: 500; color: #111;\">Gionee Handsfree Type-C</div>\n          </td>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee; text-align: center;\">1</td>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee; text-align: right;\">PKR 600</td>\n        </tr>\n      \n            </tbody>\n          </table>\n          \n          <div style=\"margin-top: 20px; text-align: right;\">\n            <p><strong>Delivery Fee:</strong> PKR 200</p>\n            <p style=\"font-size: 1.25rem; color: #ff6b00;\"><strong>Total Amount:</strong> PKR 800</p>\n          </div>\n        "}','{"id":"67e8ae66-278c-40c6-b0be-c2431da66bda"}',NULL,'2026-06-21 13:36:20');
