INSERT INTO "resend_email_logs" ("id","type","order_id","recipient","subject","payload","response","error","created_at") VALUES(939,'Admin Alert','#GPK07190','support@gionee.com.pk, aashirblogging@gmail.com','New Order: #GPK07190 - Jatta','{"from":"Gionee Orders <order@gionee.com.pk>","to":["support@gionee.com.pk","aashirblogging@gmail.com"],"subject":"New Order: #GPK07190 - Jatta","html":"\n          <h3>New Order Confirmation - #GPK07190</h3>\n          <h4>Customer Details</h4>\n          <p><strong>Name:</strong> Jatta</p>\n          <p><strong>Phone:</strong> 03476810646</p>\n          <p><strong>Email:</strong> uniquecafe619@gmail.com</p>\n          <p><strong>City:</strong> Gujranwala cant</p>\n          <p><strong>Address:</strong> Garden town phase 3 b block </p>\n          \n          <h4>Order Items</h4>\n          <table style=\"width: 100%; border-collapse: collapse; margin-top: 10px;\">\n            <thead>\n              <tr style=\"background: #f8f8f8;\">\n                <th style=\"padding: 8px; text-align: left;\">Item</th>\n                <th style=\"padding: 8px; text-align: center;\">Qty</th>\n                <th style=\"padding: 8px; text-align: right;\">Price</th>\n              </tr>\n            </thead>\n            <tbody>\n              \n        <tr>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee;\">\n            <div style=\"font-weight: 500; color: #111;\">Gionee Handsfree 3.5mm</div>\n          </td>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee; text-align: center;\">2</td>\n          <td style=\"padding: 12px; border-bottom: 1px solid #eee; text-align: right;\">PKR 500</td>\n        </tr>\n      \n            </tbody>\n          </table>\n          \n          <div style=\"margin-top: 20px; text-align: right;\">\n            <p><strong>Delivery Fee:</strong> PKR 200</p>\n            <p style=\"font-size: 1.25rem; color: #ff6b00;\"><strong>Total Amount:</strong> PKR 1,200</p>\n          </div>\n        "}','{"id":"009163db-56a6-4062-ae3d-8fa347b52116"}',NULL,'2026-07-31 09:49:59');
