INSERT INTO "resend_email_logs" ("id","type","order_id","recipient","subject","payload","response","error","created_at") VALUES(946,'Order Placed','#GPK07194','gillalihaider8@gmail.com','Your Order #GPK07194 is Received!','{"from":"Gionee Pakistan <orders@gionee.com.pk>","to":["gillalihaider8@gmail.com"],"subject":"Your Order #GPK07194 is Received!","html":"<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"ie=edge\">\r\n    <title>Gionee Pakistan - Order Confirmation</title>\r\n    <!-- Google Fonts: Outfit -->\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\r\n    \r\n    <style>\r\n        /* Outlook and client compatibility resets */\r\n        body, table, td, a { \r\n            -webkit-text-size-adjust: 100%; \r\n            -ms-text-size-adjust: 100%; \r\n        }\r\n        table, td { \r\n            mso-table-lspace: 0pt; \r\n            mso-table-rspace: 0pt; \r\n        }\r\n        img { \r\n            -ms-interpolation-mode: bicubic; \r\n            border: 0; \r\n            height: auto; \r\n            line-height: 100%; \r\n            outline: none; \r\n            text-decoration: none; \r\n        }\r\n        table { \r\n            border-collapse: collapse !important; \r\n        }\r\n        body { \r\n            height: 100% !important; \r\n            margin: 0 !important; \r\n            padding: 0 !important; \r\n            width: 100% !important; \r\n            background-color: #f8f9fa; \r\n            font-family: ''Outfit'', -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif;\r\n        }\r\n\r\n        /* Prevent Outlook from defaulting to Times New Roman when Outfit is missing */\r\n        [style*=\"Outfit\"] {\r\n            font-family: ''Outfit'', -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif !important;\r\n        }\r\n\r\n        /* Mobile Responsive Styles */\r\n        @media screen and (max-width: 600px) {\r\n            .email-container {\r\n                width: 100% !important;\r\n                max-width: 100% !important;\r\n                padding: 10px !important;\r\n            }\r\n            .content-body {\r\n                padding: 24px 16px !important;\r\n            }\r\n            .order-summary-card {\r\n                padding: 16px !important;\r\n            }\r\n            .footer {\r\n                padding: 24px 16px !important;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body style=\"background-color: #f5f6f8; margin: 0; padding: 0;\">\r\n\r\n    <!-- Main background wrapper -->\r\n    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: #f5f6f8; table-layout: fixed;\">\r\n        <tr>\r\n            <td align=\"center\" style=\"padding: 40px 10px;\">\r\n                \r\n                <!-- Email container block -->\r\n                <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" class=\"email-container\" style=\"background-color: #ffffff; border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.04); overflow: hidden; border: 1px solid #eef1f4;\">\r\n                    \r\n                    <!-- Header Section with White Background and Dark Logo -->\r\n                    <tr>\r\n                        <td align=\"center\" style=\"padding: 10px; background-color: #ffffff; border-bottom: 1px solid #f0f0f2;\">\r\n                            <a href=\"https://gionee.com.pk/\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\r\n                                <img src=\"