PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT UNIQUE NOT NULL,
    title TEXT NOT NULL,
    base_price REAL NOT NULL,
    original_price REAL,
    description TEXT NOT NULL,
    long_description TEXT,
    badge TEXT,
    meta_title TEXT NOT NULL,
    meta_description TEXT NOT NULL,
    images TEXT NOT NULL,       -- JSON string array of R2 URLs: ["https://media.gionee.com.pk/img.jpg", ...]
    specs TEXT NOT NULL,        -- JSON array of key-value objects: [{"label": "Connector", "value": "USB-C"}]
    features TEXT NOT NULL,     -- JSON array of feature objects: [{"title": "Bass", "description": "Punchy bass"}]
    compatibility TEXT NOT NULL, -- JSON string array: ["Samsung S23", "iPhone 15", ...]
    faqs TEXT NOT NULL,         -- JSON array of FAQ objects: [{"question": "Q?", "answer": "A"}]
    review_count INTEGER DEFAULT 1000,
    rating REAL DEFAULT 4.8,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, status TEXT DEFAULT 'published', cost_price REAL NOT NULL DEFAULT 0);
CREATE TABLE product_packs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER NOT NULL,
    pack_label TEXT NOT NULL,   -- e.g. "Pack of 3", "Single", "Pack of 5"
    unit_count INTEGER NOT NULL, -- e.g. 3, 1, 5
    pack_price REAL NOT NULL,    -- Custom pricing, e.g. 1500 (instead of 1650)
    free_shipping INTEGER NOT NULL DEFAULT 0, -- 0 = False, 1 = True (Free shipping toggle)
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
);
CREATE TABLE orders (
    id TEXT PRIMARY KEY,
    customer_name TEXT NOT NULL,
    customer_phone TEXT NOT NULL,
    customer_email TEXT,
    city TEXT NOT NULL,
    address TEXT NOT NULL,
    delivery_fee REAL NOT NULL,
    total_amount REAL NOT NULL,
    status TEXT NOT NULL DEFAULT 'Pending',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, tracking_no TEXT, courier_order_id TEXT, courier_status TEXT, whatsapp_confirmed INTEGER DEFAULT 0, shipped_at TEXT, delivered_at TEXT, whatsapp_chat_id TEXT, payment_status TEXT NOT NULL DEFAULT 'Pending', return_status TEXT NOT NULL DEFAULT 'Pending', tracking_notes TEXT DEFAULT '', order_summary TEXT);
CREATE TABLE order_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id TEXT NOT NULL,
    product_id INTEGER NOT NULL,
    product_name TEXT NOT NULL,
    unit_price REAL NOT NULL,
    quantity INTEGER NOT NULL,
    pack_size_label TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
);
CREATE TABLE reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_id INTEGER NOT NULL,
    rating REAL NOT NULL,
    title TEXT,
    text TEXT NOT NULL,
    author TEXT NOT NULL,
    location TEXT,
    is_visible INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
);
CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    description TEXT,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE order_timeline (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id TEXT NOT NULL,
    status TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
);
CREATE TABLE webhook_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                sender TEXT,
                message TEXT,
                payload TEXT,
                status TEXT,
                response TEXT
            );
CREATE TABLE users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            salt TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE sessions (
            id TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            expires_at TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE rs_courier_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                action TEXT NOT NULL,
                order_id TEXT,
                tracking_no TEXT,
                payload TEXT,
                response TEXT,
                error TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE resend_email_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                type TEXT NOT NULL,
                order_id TEXT,
                recipient TEXT NOT NULL,
                subject TEXT,
                payload TEXT,
                response TEXT,
                error TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE monthly_expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    month TEXT UNIQUE NOT NULL,
    ad_spend REAL NOT NULL DEFAULT 0,
    other_expenses REAL NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE gotify_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                order_id TEXT,
                message TEXT,
                payload TEXT,
                status TEXT,
                response TEXT
            );
DELETE FROM sqlite_sequence;
